const crypto = require('crypto');

// Signs a body for Convex with N8N_TO_CONVEX_SECRET (an env var, never stored
// in this workflow). Convex checks the signature and rejects timestamps older
// than 5 minutes.
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, timestamp, signature };
}

// Convex works out "overdue" and "not reminded today" on its side.
return [{ json: signForConvex({}) }];

// One reminder per overdue loan. Convex sends only the borrower's name and
// email, the tool name, the due date and how many days late it is.
const loan = $json;
const days = loan.daysOverdue === 1 ? '1 day' : loan.daysOverdue + ' days';
return {
  json: {
    idempotencyKey: loan.reminderKey,
    loanId: loan.loanId,
    to: loan.borrower.email,
    subject: 'Reminder: the ' + loan.toolName + ' was due back ' + days + ' ago',
    text: 'Hi ' + loan.borrower.name + ',\n\nThe ' + loan.toolName + ' you borrowed was due back on ' + loan.endDate +
      '. Please return it or message the owner in LendLoop.\n\nLendLoop',
  },
};

// Mock email provider: logs instead of sending. To go live, replace this node
// with a Gmail / SMTP / SendGrid node and keep the same retry and
// "continue (using error output)" settings.
// Addresses ending in @fail.test simulate a provider outage, to demo the
// retry → failed write-back path.
const to = $json.to;
if (to.endsWith('@fail.test')) {
  throw new Error('Mock provider: mailbox unavailable');
}
// Log a masked address only: execution logs are not the place for PII.
const masked = to.replace(/^(.).*@/, '$1***@');
console.log('[mock-email] to=' + masked + ' subject="' + $json.subject + '"');
return { json: { delivered: true, channel: 'mock-email' } };

const crypto = require('crypto');

// Signs a body for Convex with N8N_TO_CONVEX_SECRET (an env var, never stored
// in this workflow). Convex checks the signature and rejects timestamps older
// than 5 minutes.
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, timestamp, signature };
