// Runs for both outputs of "Send email (mock)". The idempotency key is
// reminder:<loanId>:<date>, so a retried write-back updates the same record.
const msg = $('Compose reminder').item.json;
const sent = $json.delivered === true;

return {
  json: signForConvex({
    idempotencyKey: msg.idempotencyKey,
    loanId: msg.loanId,
    kind: 'reminder',
    status: sent ? 'sent' : 'failed',
    channel: 'mock-email',
    detail: sent ? 'Overdue reminder' : 'Email failed after 3 tries',
  }),
};
